# Let me check 8-connectivity for 5s
def find_connected_regions(grid, color, connectivity=8):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    visited = set()
    regions = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == color and (r,c) not in visited:
                region = []
                stack = [(r,c)]
                while stack:
                    rr, cc = stack.pop()
                    if (rr, cc) in visited:
                        continue
                    visited.add((rr, cc))
                    region.append((rr, cc))
                    # Add neighbors based on connectivity
                    for dr in set([-1, 0, 1]):
                        for dc in set([-1, 0, 1]):
                            if dr == 0 and dc == 0:
                                continue
                            if connectivity == 4 and (dr != 0 and dc != 0):
                                continue  # Diagonal not allowed

                            nr, nc = rr + dr, cc + dc
                            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == color and (nr, nc) not in visited:
                                stack.append((nr, nc))
                regions.append(region)

    return regions

